///    /// <summary>
/// Set form configuration.
/// </summary>
/// <param name = "String">query string</param>
/// <returns>A <c>string</c> object.</returns>

/// <summary>
/// Retrieve query
/// </summary>
/// <parameter>string</parameter>
/// <returns>A <c>str</c> object.</returns>
[DataMemberAttribute,AifQueryTypeAttribute('_queryString', queryStr(AVADAIExportProtocolCleanUpQuery))]
public str parmQueryString(str _queryString = queryString)
{
    queryString = _queryString;
    return queryString;
}

/// <summary>
/// Retrieve query
/// </summary>
/// <returns>A <c>Query</c> object.</returns>
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(queryString));
}
